-- Do cached and uncached distance agree?
SELECT c, abs(ST_Distance(ply::geography, pt::geography) - _ST_DistanceUnCached(ply::geography, pt::geography)) < 0.01 FROM
( VALUES
('geog_distance_cached_1a', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(5 5)'),
('geog_distance_cached_1b', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(5 5)'),
('geog_distance_cached_1c', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(5 5)'),
('geog_distance_cached_1e', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(5 5)'),
('geog_distance_cached_1f', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(5 5)'),
('geog_distance_cached_1g', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(5 5)'),
('geog_distance_cached_1h', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(5 5)')
) AS u(c,ply,pt);

-- Does tolerance based distance work cached? Inside tolerance
SELECT c, ST_DWithin(ply::geography, pt::geography, 3000) from
( VALUES
('geog_dithin_cached_1a', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(10.01 5)'),
('geog_dithin_cached_1b', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(10.01 5)'),
('geog_dithin_cached_1c', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(10.01 5)')
) as p(c, ply, pt);

-- Does tolerance based distance work cached? Outside tolerance
SELECT c, ST_DWithin(ply::geography, pt::geography, 1000) from
( VALUES
('geog_dithin_cached_2a', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(10.01 5)'),
('geog_dithin_cached_2b', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(10.01 5)'),
('geog_dithin_cached_2c', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(10.01 5)')
) as p(c, ply, pt);

-- Do things work when there's cache coherence on the point side but not the poly side?
SELECT c, ST_DWithin(ply::geography, pt::geography, 3000) from
( VALUES
('geog_dithin_cached_3a', 'POLYGON((0 0, 0 10, 10 10, 10 0, 0 0))', 'POINT(5 5)'),
('geog_dithin_cached_3b', 'POLYGON((1 1, 1 10, 10 10, 10 1, 1 1))', 'POINT(5 5)'),
('geog_dithin_cached_3c', 'POLYGON((2 2, 2 10, 10 10, 10 2, 2 2))', 'POINT(5 5)')
) as p(c, ply, pt);

-- Test a precision case near the south pole that came up during development.
WITH pt AS (
    SELECT point::geography FROM ( VALUES
    ('0101000020E61000006C5B94D920EB4CC0A0FD481119B24FC0'),
    ('0101000020E610000097A8DE1AD8524CC09C8A54185B1050C0'),
    ('0101000020E61000008FC2F5285C4F4CC0E5ED08A7050F50C0'),
    ('0101000020E61000008FC2F5285C4F4CC0E5ED08A7050F50C0') ) AS p(point)
),
ply AS (
    SELECT polygon::geography FROM ( VALUES
    ('')
    ) as q(polygon)
)
SELECT 'geog_precision_savffir', _ST_DistanceUnCached(pt.point, ply.polygon), ST_Distance(pt.point, ply.polygon) FROM pt, ply;

-- Test another precision case near the north poly and over the dateline
WITH pt AS (
    SELECT point::geography FROM ( VALUES
    ('0101000020E610000000000000004065400000000000804840'),
    ('0101000020E610000075C8CD70033965C02176A6D079315040') ) AS p(point)
),
ply AS (
    SELECT polygon::geography FROM ( VALUES
    ('')
    ) as q(polygon)
)
SELECT 'geog_precision_pazafir', _ST_DistanceUnCached(pt.point, ply.polygon), ST_Distance(pt.point, ply.polygon) FROM pt, ply;

-- #2941
CREATE TABLE test(id integer, geog geography(multilinestring,4269));
INSERT INTO test VALUES (1, 'SRID=4269;MULTILINESTRING((0 0, 1 1))');
SELECT id,ST_AsText(geog) FROM test;
DROP TABLE test;

-- #2422
CREATE TABLE dwithgeogbug (
    gid integer,
    geog geography
);
INSERT INTO dwithgeogbug (gid, geog) VALUES (1, '');
INSERT INTO dwithgeogbug (gid, geog) VALUES (2, '');
SELECT
'#2422' as ticket, gid, radius,
_ST_DWithin(geog, tgeog, radius, true) AS dwithin_t,
_ST_DWithin(geog, tgeog, radius, false) AS dwithin_f,
round(ST_Distance(geog, tgeog, true)::numeric,3) AS distance_t,
round(ST_Distance(geog, tgeog, false)::numeric,3) AS distance_f,
round(_ST_DistanceUnCached(geog, tgeog)::numeric,3) AS distance_uncached,
round(_ST_DistanceTree(geog, tgeog)::numeric,3) AS distance_tree
FROM dwithgeogbug
CROSS JOIN ST_GeogFromText('POINT(-69.83262 43.43636)') AS tgeog
CROSS JOIN (VALUES (1609),(1600),(1068)) AS t (radius)
ORDER BY distance_t;
DROP TABLE dwithgeogbug;

-- Test segmentize on geography
-- Check that the maximum sphere distance over all the segments is lesser than the max distance used for segmentize
WITH
seg as (select ST_Segmentize('LINESTRING(0 0 10,0 90 20)'::geography, 50000)::geometry as geom),
dumped as (SELECT (st_dumppoints(geom)).path[1] as id, (st_dumppoints(geom)).geom from seg)
SELECT 'segmentize_geography', max(st_distance(d1.geom::geography, d2.geom::geography, false))::int FROM dumped as d1, dumped as d2 where d2.id = d1.id + 1;

-- Check that st_segmentize creates segments on the geodesic path
SELECT 'segmentize_geography2', st_dwithin(st_pointn(st_segmentize('linestring(1 47,-64 47)'::geography, 3000000)::geometry, 2), 'SRID=4326;POINT(-31.5 51.81)'::geometry, 0.01);

-- #bug 3667
SELECT 'segmentize_geography_3667', abs(ST_Length(geog) - ST_Length(ST_Segmentize(geog, 30000))) < 0.00001
  FROM (SELECT ST_GeographyFromText('LINESTRING(38.769917 10.780694, 38.769917 9.106194)') As geog) AS f;

-- typmod checks
select 'typmod_point_4326', geography_typmod_out(geography_typmod_in('{Point,4326}'));
select 'typmod_point_0', geography_typmod_out(geography_typmod_in('{Point,0}'));
select 'typmod_point_-1', geography_typmod_out(geography_typmod_in('{Point,-1}'));
select 'typmod_pointzm_0', geography_typmod_out(geography_typmod_in('{PointZM,0}'));
select 'typmod_geometry_0', geography_typmod_out(geography_typmod_in('{Geometry,0}'));
select 'typmod_geometry_4326', geography_typmod_out(geography_typmod_in('{Geometry,4326}'));
select 'typmod_geography_0', geography_typmod_out(geography_typmod_in('{Geogrpahy,0}'));

-- ST_DWithin
select 'dwithin_pt_pt_1', ST_DWithin('POINT(0 0)'::geography, 'POINT(1 1)'::geography, 300000);
select 'dwithin_pt_pt_2', ST_DWithin('POINT(0 0)'::geography, 'POINT(1 1)'::geography, 10);
select 'dwithin_pt_line_1', ST_DWithin('POINT(0 0)'::geography, 'LINESTRING(1 1, 2 2)'::geography, 300000);
select 'dwithin_line_pt_1', ST_DWithin('LINESTRING(1 1, 2 2)'::geography, 'POINT(0 0)'::geography, 300000);
select 'dwithin_pt_poly_1', ST_DWithin('POINT(0 0)'::geography, 'POLYGON((1 1, 2 2, 3 0, 1 1))'::geography, 300000);
select 'dwithin_poly_pt_1', ST_DWithin('POLYGON((1 1, 2 2, 3 0, 1 1))'::geography, 'POINT(0 0)'::geography, 300000);
select 'dwithin_line_poly_1', ST_DWithin('LINESTRING(-1 -1, 0 0)'::geography, 'POLYGON((1 1, 2 2, 3 0, 1 1))'::geography, 300000);
select 'dwithin_poly_line_1', ST_DWithin('POLYGON((1 1, 2 2, 3 0, 1 1))'::geography, 'LINESTRING(-1 -1, 0 0)'::geography, 300000);
select 'dwithin_poly_poly_1', ST_DWithin('POLYGON((0 0, -2 -2, -3 0, 0 0))'::geography, 'POLYGON((1 1, 2 2, 3 0, 1 1))'::geography, 10);
select 'dwithin_poly_poly_2', ST_DWithin('POLYGON((0 0, -2 -2, -3 0, 0 0))'::geography, 'POLYGON((1 1, 2 2, 3 0, 1 1))'::geography, 300000);
select 'dwithin_poly_poly_3', ST_DWithin('POLYGON((1 1, -2 -2, -3 0, 1 1))'::geography, 'POLYGON((1 1, 2 2, 3 0, 1 1))'::geography, 300000);

WITH expanded AS (
	SELECT _ST_Expand('POINT(-74.028349 40.737980)'::geography, 10000) AS geog
)
SELECT '#4122',
       pg_typeof(geog),
       near_probe && geog,
       near_probe && geog::text::geography,
       near_probe && geog::bytea::geography,
       far_probe && geog,
       far_probe && geog::text::geography,
       far_probe && geog::bytea::geography
FROM expanded,
     (SELECT 'POINT(-73.95 40.737980)'::geography AS near_probe,
             'POINT(-10 0)'::geography AS far_probe) AS p;

WITH expanded AS (
	SELECT _ST_Expand('POINT(112.43006556 -20.55138435)'::geography, 496381) AS geog
)
SELECT '#4122-expanded-carrier',
       probe && geog,
       probe && geog::text::geography,
       probe && geog::bytea::geography
FROM expanded,
     (SELECT 'POINT(116.13433622 -23.40307415)'::geography AS probe) AS p;


