-- #5895: a distant point whose stab line passes close to a polygon vertex.
WITH input AS (
  SELECT ST_GeomFromText('POLYGON((
    -93.751932270476971 32.089230804932349,
    -93.753830066356031 32.089181143046332,
    -93.753864556452115 32.090802706180867,
    -93.751940314782857 32.09084654939128,
    -93.751932270476971 32.089230804932349
  ))', 4326) AS poly, ST_Point(52.41828388240291, 28.68513149020453, 4326) AS pt
)
SELECT '#5895.sphere', round(ST_DistanceSphere(poly, pt)::numeric, 3)::text FROM input
UNION ALL
SELECT '#5895.distance', round(ST_Distance(poly::geography, pt::geography)::numeric, 3)::text
FROM input
UNION ALL
SELECT '#5895.closest', ST_AsText(ST_ClosestPoint(poly::geography, pt::geography), 6)
FROM input;

